package io.github.jesterportfolio.hearth.combat;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.combat.CombatContent.*;

class CombatRouteTest {
    static Route route(){return new Route(List.of(new Section("first_path","첫 길목",new FieldContent.Box(0,6,63,68,0,6),new Exit(new FieldContent.Point(20,64,20),0,0,1,List.of()),"rest_one"),new Section("second_path","둘째 길목",new FieldContent.Box(19,24,63,68,19,24),new Exit(new FieldContent.Point(30,64,30),0,0,1,List.of()),null)),"second_path");}
    static final class F {final CombatPlayersTest.Fixture f=new CombatPlayersTest.Fixture();boolean valid=true,checkpoint=true;final CompletableFuture<Void> save=new CompletableFuture<>();final CombatRoute route=new CombatRoute(f.fight,route(),false,f.owner,()->{},()->valid&&f.generation.get()==1);UUID id=UUID.randomUUID();CompletionStage<Void> begin(){return route.advance("first_path",id,List.of(f.p,f.q),()->save,()->checkpoint);}void pump(){f.pump();}void saved(){save.complete(null);pump();}void apply(){f.p.applying.complete(true);pump();f.q.applying.complete(true);pump();}}
    @Test void savedBeforeMoveAndSameAttemptRosterCountersAndHealthArePreserved(){var x=new F();x.f.p.health=.6;x.f.q.health=.8;var before=x.f.fight.snapshot();var result=x.begin();assertSame(result,x.begin());x.pump();assertEquals(0,x.f.p.restores);assertFalse(x.route.barrier().toCompletableFuture().isDone());x.saved();x.apply();result.toCompletableFuture().join();assertEquals(1,x.route.index());assertEquals(CombatRoute.Phase.DONE,x.route.phase());assertEquals(before,x.f.fight.snapshot());assertEquals(.6,x.f.p.health);assertEquals(.8,x.f.q.health);assertFalse(x.f.p.applyGuard.getAsBoolean());}
    @Test void wrongSectionCheckpointAndOutsideAreaDoNotSave(){var x=new F();assertTrue(x.route.advance("second_path",x.id,List.of(x.f.p,x.f.q),()->{fail();return x.save;},()->true).toCompletableFuture().isCompletedExceptionally());x.checkpoint=false;assertTrue(x.begin().toCompletableFuture().isCompletedExceptionally());x.checkpoint=true;x.f.p.position=new Pose(x.f.world,99,64,99,0,0);assertTrue(x.begin().toCompletableFuture().isCompletedExceptionally());assertEquals(CombatRoute.Phase.IDLE,x.route.phase());assertEquals(0,x.f.p.restores);}
    @Test void deadSpectatorAndOfflineOriginalMemberAreRetainedWithoutFreeRevive(){var x=new F();x.f.bridge.died(x.f.q);x.f.bridge.project();var before=x.f.fight.snapshot();var result=x.begin();x.saved();x.f.p.applying.complete(true);x.pump();result.toCompletableFuture().join();assertEquals(0,x.f.q.restores);assertTrue(x.f.q.spectator);assertEquals(before,x.f.fight.snapshot());assertTrue(x.f.fight.snapshot().members().stream().anyMatch(m->m.player().equals(x.f.q.ctx.playerId())&&m.dead()));
        var y=new F();y.f.bridge.leave(y.f.q);var members=y.f.fight.snapshot().members();var pending=y.route.advance("first_path",y.id,List.of(y.f.p),()->y.save,()->true);y.saved();y.f.p.applying.complete(true);y.pump();pending.toCompletableFuture().join();assertEquals(members,y.f.fight.snapshot().members());var back=new CombatPlayersTest.Body(y.f.q.ctx,y.f.q.position);y.f.bridge.rejoin(back);assertEquals(2,y.f.fight.onlineSessions().size());}
    @Test void missingOrOtherRunRosterIsRejected(){var x=new F();assertTrue(x.route.advance("first_path",x.id,List.of(x.f.p),()->x.save,()->true).toCompletableFuture().isCompletedExceptionally());var other=new F();assertTrue(x.route.advance("first_path",x.id,List.of(other.f.p,other.f.q),()->x.save,()->true).toCompletableFuture().isCompletedExceptionally());assertEquals(0,x.route.index());}
    @Test void saveFailurePreservesIndexSourceAndDoesNotMove(){var x=new F();var before=x.f.fight.snapshot();var result=x.begin();x.pump();x.save.completeExceptionally(new IllegalStateException("DB_DOWN"));x.pump();assertTrue(result.toCompletableFuture().isCompletedExceptionally());assertEquals(CombatRoute.Phase.HOLD,x.route.phase());assertEquals(0,x.route.index());assertEquals(before,x.f.fight.snapshot());assertEquals(0,x.f.p.restores);assertTrue(x.route.barrier().toCompletableFuture().isCompletedExceptionally());}
    @Test void leavingGatheringDuringSaveNeverMoves(){var x=new F();var result=x.begin();x.pump();x.f.p.position=new Pose(x.f.world,100,64,100,0,0);x.saved();assertTrue(result.toCompletableFuture().isCompletedExceptionally());assertEquals(0,x.f.p.restores);}
    @Test void changedSessionGenerationCheckpointAndCloseRejectLateApply(){for(int kind=0;kind<4;kind++){var x=new F();var result=x.begin();x.saved();assertTrue(x.f.p.applyGuard.getAsBoolean());if(kind==0)x.f.bridge.leave(x.f.q);if(kind==1)x.f.generation.incrementAndGet();if(kind==2)x.checkpoint=false;if(kind==3)x.route.close();assertFalse(x.f.p.applyGuard.getAsBoolean());x.apply();assertTrue(result.toCompletableFuture().isCompletedExceptionally());assertEquals(0,x.route.index());}}
    @Test void unsafeFalseAndExceptionalMoveHoldWithoutAdvancing(){for(int k=0;k<3;k++){var x=new F();if(k==0)x.f.p.safe=false;var result=x.begin();x.saved();if(k==1)x.f.p.applying.complete(false);if(k==2)x.f.p.applying.completeExceptionally(new IllegalStateException("MOVE_FAILURE"));x.pump();assertTrue(result.toCompletableFuture().isCompletedExceptionally());assertEquals(CombatRoute.Phase.HOLD,x.route.phase());assertEquals(0,x.route.index());}}
    @Test void operationConflictAndOldRequestCannotSkipAnotherSection(){var x=new F();var first=x.begin();assertTrue(x.route.advance("first_path",UUID.randomUUID(),List.of(x.f.p,x.f.q),()->x.save,()->true).toCompletableFuture().isCompletedExceptionally());x.saved();x.apply();assertSame(first,x.route.advance("first_path",x.id,List.of(x.f.p,x.f.q),()->x.save,()->true));assertEquals(1,x.route.index());var second=x.route.advance("second_path",UUID.randomUUID(),List.of(x.f.p,x.f.q),()->CompletableFuture.completedFuture(null),()->true);x.pump();second.toCompletableFuture().join();assertTrue(x.route.atBoss());assertEquals(2,x.route.index());assertTrue(x.route.advance("second_path",UUID.randomUUID(),List.of(x.f.p,x.f.q),()->x.save,()->true).toCompletableFuture().isCompletedExceptionally());}
    @Test void configuredRestartSectionIsUsedWithoutInferringLatestCheckpoint(){var x=new F();var restarted=new CombatRoute(x.f.fight,route(),true,x.f.owner,()->{},()->true);assertEquals(1,restarted.index());var terminal=new CombatRoute(x.f.fight,new Route(route().sections(),"boss_gate"),true,x.f.owner,()->{},()->true);assertTrue(terminal.atBoss());assertEquals(0,x.route.index());}
    @Test void otherRunContinuesAfterFailureAndAllDeadCannotAdvance(){var x=new F();var other=new F();x.valid=false;assertTrue(x.begin().toCompletableFuture().isCompletedExceptionally());var ok=other.begin();other.saved();other.apply();ok.toCompletableFuture().join();assertEquals(1,other.route.index());var dead=new F();dead.f.bridge.died(dead.f.p);dead.f.bridge.died(dead.f.q);assertTrue(dead.begin().toCompletableFuture().isCompletedExceptionally());}
    @Test void ownerRejectionBecomesFailureRatherThanPendingSuccess(){var x=new F();x.f.reject.set(true);var result=x.begin();assertTrue(result.toCompletableFuture().isCompletedExceptionally());assertEquals(CombatRoute.Phase.HOLD,x.route.phase());assertEquals(0,x.route.index());}
    @Test void contentRejectsDuplicateMissingOrRecoveryPolicies(){var definition=route();assertThrows(IllegalArgumentException.class,()->new Route(List.of(definition.sections().getFirst(),definition.sections().getFirst()),"first_path"));assertThrows(IllegalArgumentException.class,()->new Route(definition.sections(),"unknown"));assertThrows(IllegalArgumentException.class,()->new Section("boss_gate","예약 이름",definition.sections().getFirst().gathering(),definition.sections().getFirst().nextEntry(),null));assertThrows(IllegalArgumentException.class,()->new Section("one","허용하지 않는 회복",definition.sections().getFirst().gathering(),new Exit(new FieldContent.Point(2,64,2),0,0,.5,List.of()),null));var c=CombatAttemptTest.content(Pool.SHARED,2,LocationMode.START);assertThrows(IllegalArgumentException.class,()->new Path(c,definition.sections().getFirst().gathering(),definition.sections().getFirst().nextEntry(),null,null,List.of(),definition));}
}
